P(X = 8) = \binom{10}{8} \left(\frac{1}{2}\right)^8 \left(\frac{1}{2}\right)^2 = \binom{10}{8} \left(\frac{1}{2}\right)^{10} = 45 \left(\frac{1}{1024}\right) = \frac{45}{1024}
\]
